          const gt = e.target.closest("button[data-gturbo]");
          if (gt) { const r = world.getNodeState("register"); inj(0, "setturbog", { on: !r?.turbo }); return; }
          { const gl = e.target.closest("button[data-gwattloc]"); if (gl) { inj(0, "wattlocal", { on: !world.getNodeState("register")?.wattLocal }); return; } }   // ◎local ψATT (replicated)
          const gw = e.target.closest("button[data-gwatt]");
          if (gw) { const s0 = world.getNodeState("slot_0"); const on = (s0?.digestLeft ?? 0) > 0 || !!s0?.psiAtt; inj(0, "setwattg", { bars: on ? 0 : 8 }); return; }   // toggle: on → OFF (clear), off → digest 8 bars → adopt
          const qe = e.target.closest("button[data-qedge]");   // ℍ quaternion pair (slots 0,1) — SU(2) coupling
