              let ea = 0, eb = 0; const a = st.att; if (a?.re) for (let c = 0; c < N; c++) ea += a.re[c] * a.re[c] + (a.im ? a.im[c] * a.im[c] : 0); for (let c = 0; c < N; c++) eb += src.re[c] ** 2 + src.im[c] ** 2;
