          { const _eb = e.target.closest("button[data-embragg]"); if (_eb) { const it = _emitOf(_viewSlot), stB = world.getNodeState("slot_" + _viewSlot); if (!it || !it.nat || !stB) return;   // ✦ ⇢Bragg: the beam's |k| → the phase-matched shell (replicated tileput)
              const th = Math.atan2(+it.ky || 0, +it.kx || 0), b = _braggBest(stB, th); if (!b) return; const kEl = _emRoot()?.querySelector('input[data-em="k"]'); if (kEl) kEl.value = String(2 * Math.PI * b.K / G);
              _emitSend(_viewSlot); _braggKey = ""; return; } }
          { const _emd = e.target.closest("button[data-emdel]"); if (_emd) { for (const it of (world.getNodeState("slot_" + _viewSlot)?.tileItems || []).filter((x) => x.kind === "source" && x.label === "emit")) inj(_viewSlot, "tiledel", { t: it.t }); return; } }   // ✦ remove the emitter (replicated) — every 'emit' item (a session from before the one-per-slot rule may hold two)
          { const _hob = e.target.closest("button[data-holo]"); if (_hob) { const r = world.getNodeState("register"); inj(0, "hololive", r?.holoLive ? { on: false } : { on: true, patch: { view: "rec" } }); return; } }   // ◐ HOLO display mode for every slot (replicated settings); the static plate record stays on the console (ahc.holo)
