            const tx = Math.max(0, Math.min(T - 1, Math.floor((e.clientX - r.left) / r.width * T))), ty = Math.max(0, Math.min(T - 1, Math.floor((e.clientY - r.top) / r.height * T))), k = ty * T + tx;
